def test_agent_outcomes_and_dropped_list(run_dirs):
    slug_root, _ = run_dirs
    (slug_root / "agents.tsv").write_text(
        "# name\tmode\tstatus\n"
        "d1\tpropose\tok\n"
        "d2\tpropose\tok\n"
        "d3\ttriage\terror: no response\n"
    )
    outcomes, dropped = run_report.read_agents(slug_root)
