def test_search_counts_engines_and_single_wave(run_dirs):
    slug_root, _ = run_dirs
    (slug_root / "search" / "q1.json").write_text(
        '{"results": [{"url": "https://a"}, {"url": "https://b"}],'
        ' "coverage": {"wave_a_backends": "brave,google",'
        ' "wave_b_backends": "yandex", "single_wave": false,'
        ' "unique_by_wave": {"A": 2}}}'
    )
    (slug_root / "search" / "q2.json").write_text(
        '{"results": [{"url": "https://c"}],'
        ' "coverage": {"wave_a_backends": "brave", "wave_b_backends": "yandex",'
        ' "single_wave": true, "unique_by_wave": {"A": 1}}}'
    )
    stats = run_report.read_search(slug_root)
    assert stats.queries == 2
    assert stats.results == 3
    assert stats.single_wave == 1
    assert set(stats.engines) == {"brave", "google", "yandex"}
    assert stats.unique_by_wave["A"] == 3


def test_unparsable_search_file_is_counted_not_swallowed(run_dirs):
    slug_root, _ = run_dirs
    (slug_root / "search" / "bad.json").write_text("{not json")
