def test_fetch_tallies_status_and_failure_codes(run_dirs):
    slug_root, _ = run_dirs
    _fetched(slug_root, "a.md", "OK")
    _fetched(slug_root, "b.md", "FAILED (403: blocked)")
    _fetched(slug_root, "c.md", "FAILED (404: gone)")
    (slug_root / "fetched" / "a.md.refs").write_text("https://ref1\nhttps://ref2\n")
    stats = run_report.read_fetched(slug_root)
    assert (stats.total, stats.ok, stats.failed) == (3, 1, 2)
    assert stats.reasons["403"] == 1 and stats.reasons["404"] == 1
    assert stats.refs == 2


