def test_citation_tiers_orphans_and_access_failures(run_dirs):
    _, deliverable = run_dirs
    (deliverable / "citations.md").write_text(
        "**[1]** A\n**Tier:** 1\nnote\n\n"
        "**[2]** B\n**Tier:** 4\n**Access:** FAILED (404)\n\n"
        "**[3]** C\n**Tier:** 2\n"
    )
    (deliverable / "analysis.md").write_text("Claim [1] and [2].")
    stats = run_report.read_citations(deliverable)
    assert stats.defined == 3
    assert stats.cited == 2  # [3] is an orphan
    assert stats.access_failed == 1
    assert stats.tiers == {"Tier 1": 1, "Tier 4": 1, "Tier 2": 1}


