    (slug_root / "agents.tsv").write_text("a\tpropose\tok\nb\ttriage\ttimeout\n")
    _fetched(slug_root, "a.md", "OK")
    (deliverable / "citations.md").write_text(
        "**[1]** A\n**Tier:** 1\n\n**[2]** B\n**Tier:** 2\n"
    )
    (deliverable / "analysis.md").write_text("[1] [2]")
